"""B2 lessons for convert_a2c2_v3.py. First option of every list is the correct answer."""


def build(ch, fill, bank):
    return {
        "b2-projects": dict(
            tip="Report a problem with “slipped by”: “The launch slipped by two weeks.” “Would rather… than” states a preference: “I would rather delay than ship it.” “Even though” admits a fact that points the other way: “Even though we had a date, we waited.” A blocking bug stops users from finishing a task.",
            read=("A short delay.", "An earlier date.", "A bigger team.", "A public launch."),
            listen=("Pilot users found a blocking bug.", "The budget ran out.", "The team left the project.", "The date was never set."),
            gram=[("slipped", "slip", "slips", "slipping"), ("would rather", "would better", "will better", "could rather"),
                  ("because", "although", "unless", "so that"), ("Even though", "Unless", "Therefore", "So that")],
            tf=("The team shipped on the planned date.", False, "Pilot users found a blocking bug, so the launch slipped by two weeks."),
            dict="The launch slipped by two weeks because of a blocking bug.",
        ),
        "b2-leadership": dict(
            tip="A lead “invites dissent” early: they ask for disagreement before a decision. “Even when” names a condition that does not change the action: “She decides even when the group is split.” “Rather than” names what you avoid. “Is responsible for” means you own the result.",
            read=("Bad news, or dissent.", "Good news only.", "A longer meeting.", "A new schedule."),
            listen=("When the group is split.", "When everyone agrees.", "When the plan is finished.", "When the budget is cut."),
            gram=[("invites", "invite", "inviting", "invited"), ("when", "that", "than", "as"), ("rather than", "other than", "instead", "more than"),
                  ("is responsible for", "responsible to", "is responsibility of", "has responsible for")],
            tf=("Mina asks people to hide bad news until the meeting ends.", False, "She invites bad news early, even when it slows the meeting."),
            dict="A good lead invites dissent early.",
        ),
        "b2-media": dict(
            tip="“Imply” means to suggest something without saying it: “The headline implied a cause.” Use “who” for people: “Readers who stopped at the headline were misled.” “Never proved” says it was not shown at all. “As if” compares with something that is not true: “It reads as if the clip were the event.”",
            read=("A viral clip.", "A news report.", "A court case.", "A weather map."),
            listen=("The cause was not proved.", "The date was wrong.", "The place was unknown.", "The names were missing."),
            gram=[("implied", "implies", "implying", "imply"), ("who", "which", "what", "whom"), ("never", "ever", "not", "hardly"),
                  ("as if", "as for", "so if", "like as")],
            tf=("The article proved the cause of the event.", False, "The article never proved it, even though the headline implied a cause."),
            dict="The headline implied a cause that was never proved.",
        ),
        "b2-social": dict(
            tip="Use cause verbs to describe an effect: “Higher rent pushes workers outward.” “Farther” compares distance: “They live farther from work than before.” “While” can mean at the same time as: “Build the line while protecting residents.” Use “who” for the people you protect.",
            read=("People who already live beside the stations.", "Commuters on the new line.", "People who live far away.", "The owners of the trains."),
            listen=("Workers.", "Shop owners.", "Students.", "Visitors."),
            gram=[("pushes", "push", "pushing", "to push"),
                  ch("farther", "far", "farthest", "fartherly", prompt="Distance: They live ___ from work than before."),
                  ("who", "which", "what", "whom"), ("while", "because", "unless", "so")],
            tf=("Mina is against building the new rail line.", False, "She wants both the line and protections for the people who live beside the stations."),
            dict="Higher rent pushes workers farther from their jobs.",
        ),
        "b2-innovation": dict(
            tip="Describe a useful change by saying what it was and what it was not: “The change was not the tool itself. It was the removal of a step.” Use “that” to link a step to its description. “Rather than” names the option you did not choose: “removal rather than another screen.”",
            read=("A step nobody could explain, kept for an old audit.", "A dashboard nobody opened.", "A new screen for the checklist.", "An old audit report."),
            listen=("Removing a step nobody could explain.", "Adding another screen.", "Opening the dashboard more often.", "Hiring a new auditor."),
            gram=[("not", "no", "never", "nothing"), ("was", "were", "been", "being"), ("that", "who", "what", "where"),
                  ("rather than", "other than", "more than", "instead")],
            tf=("The team added another screen to the dashboard.", False, "The useful change was a shorter checklist, not another screen."),
            dict="They cut the step that nobody could explain.",
        ),
        "b2-ethics": dict(
            tip="Use “if” for a condition: “If we collect it only because we can, we should stop.” Use “unless” for “except if”: “Do not keep it unless there is a named use.” “We have not earned the right” uses the present perfect. “Owe” means to have a duty to give: “We owe users an explanation.”",
            read=("A plain reason.", "A longer form.", "A free gift.", "A new field."),
            listen=("When they collect it only because they can.", "When they collect it for a named use.", "When users ask them to.", "When the law requires a report."),
            gram=[("If", "Unless", "Because", "Although"), ("have not", "has not", "are not", "did not"), ("unless", "although", "whereas", "whether"),
                  ("owe", "owes", "owing", "owned")],
            tf=("Mina would keep a data field with no named use.", False, "She will not keep a field that has no named use."),
            dict="We owe users a plain reason.",
        ),
        "b2-environment": dict(
            tip="Compare results with “more than” and “better than”: “The thermostat cut more energy than the cups did.” Use “by” for the size of a change: “by two days.” “Rather than” says which option you choose over another: “Choose the default rather than the campaign.”",
            read=("The thermostat.", "The reusable cups.", "The poster campaign.", "The bicycles."),
            listen=("Cutting the commute by two days a week.", "Hanging more posters.", "Buying more cups.", "Switching off the lights."),
            gram=[("more than", "more as", "most than", "more that"), ("by", "of", "at", "from"), ("better than", "more better than", "good than", "best than"),
                  ("rather than", "other than", "more than", "less than")],
            tf=("The reusable cups cut more energy than the thermostat.", False, "The thermostat cut energy by more than the cups did."),
            dict="The thermostat cut more energy than the cups did.",
        ),
        "b2-present": dict(
            tip="Open a presentation by stating the decision you want before the history: “I am asking you to approve the plan.” Then give facts that support it. Use “then” to show order, “by” plus an -ing verb to show the method (close by naming the ask), and “before” to set a limit.",
            read=("The ask.", "The history.", "The slides.", "The jokes."),
            listen=("The decision you want.", "The history of the project.", "The names of the team.", "The cost of the slides."),
            gram=[("then", "than", "that", "there"), ("that", "who", "what", "whom"), ("by", "at", "of", "for"), ("before", "after", "until", "because")],
            tf=("Mina starts with the history of the project.", False, "She tells new speakers to state the ask before the history."),
            dict="State the decision first, then give the facts.",
        ),
        "b2-negotiation": dict(
            tip="Offer one trade at a time. Use “if” for a condition: “We can move the date if the scope stays fixed.” “As long as” also sets a limit: “We can extend it as long as the list stays still.” Say “both” for two things together and “neither” for no side: “Neither side can defend that.”",
            read=("The deadline.", "The feature list.", "The budget.", "The team."),
            listen=("The date.", "The scope.", "The price.", "The team."),
            gram=[("if", "even", "than", "then"), ("both", "each", "either", "none"), ("Neither", "Both", "None", "Many"),
                  ("as long as", "as soon as", "as much as", "as well as")],
            tf=("Mina will give away both the date and the scope.", False, "She will extend the deadline only as long as the feature list does not grow."),
            dict="We can move the date if the scope stays fixed.",
        ),
        "b2-disagree": dict(
            tip="Disagree and still own the result. “Although I see the risk, I choose the trial.” “Still” shows you keep your choice: “I still choose the short trial.” Use “if” for what you will accept: “I will own it if it fails.” Use “while” to join two true things: “We can disagree while staying respectful.”",
            read=("Another private month.", "A public pilot.", "A shorter trial.", "No trial at all."),
            listen=("The result.", "The blame.", "The schedule.", "The budget."),
            gram=[("still", "already", "never", "yet"), ("if", "even", "that", "than"), ("Although", "Unless", "Whether", "Therefore"),
                  ("while", "because", "unless", "so")],
            tf=("Mina and her colleague disagree about respect.", False, "She says the disagreement is about evidence, not about respect."),
            dict="I see the risk, and I still choose the short trial.",
        ),
    }
